"use client";

import type { LucideIcon } from "lucide-react";
import { cn } from "@/lib/utils";
import { useMenu } from "@/hooks/use-menu";

export type MenuItem = {
  label: string;
  onSelect: () => void;
  icon?: LucideIcon;
  /** Shows a filled marker — e.g. the currently-applied sort. */
  selected?: boolean;
  disabled?: boolean;
};

export type MenuProps = {
  /** Trigger contents (text and/or icon). */
  trigger: React.ReactNode;
  items: MenuItem[];
  /** Optional heading above the items. */
  label?: string;
  /** Align the dropdown to the trigger's right edge. Defaults to left. */
  align?: "left" | "right";
  className?: string;
};

/**
 * Action dropdown: a trigger that opens a list of items, each running its
 * onSelect. Behavior (open, outside-click, Escape, arrow keys) comes from the
 * headless useMenu hook.
 */
export function Menu({ trigger, items, label, align = "left", className }: MenuProps) {
  const { open, activeIndex, setActiveIndex, containerRef, itemId, triggerProps, menuProps, onSelect } =
    useMenu({
      itemCount: items.length,
      onActivate: (i) => {
        const item = items[i];
        if (item && !item.disabled) onSelect(item.onSelect);
      },
    });

  return (
    <div ref={containerRef} className={cn("relative inline-block", className)}>
      <button
        type="button"
        {...triggerProps}
        className="inline-flex items-center gap-2 border border-white/20 px-3 py-1.5 text-sm transition-colors hover:bg-white/5"
      >
        {trigger}
      </button>

      {open && (
        <div
          {...menuProps}
          className={cn(
            "absolute top-full z-30 mt-1 min-w-48 border border-white/10 bg-black",
            align === "right" ? "right-0" : "left-0",
          )}
        >
          {label && (
            <>
              <div className="px-3 py-1.5 text-sm text-white/70">{label}</div>
              <div className="h-px bg-white/10" />
            </>
          )}
          {items.map((item, i) => {
            const Icon = item.icon;
            return (
              <button
                key={item.label}
                id={itemId(i)}
                type="button"
                role="menuitem"
                disabled={item.disabled}
                onMouseEnter={() => setActiveIndex(i)}
                onClick={() => onSelect(item.onSelect)}
                className={cn(
                  "flex w-full items-center gap-2 px-3 py-1.5 text-left text-sm transition-colors disabled:opacity-40",
                  i === activeIndex ? "bg-white/10 text-white" : "text-white/70 hover:text-white",
                )}
              >
                {item.selected !== undefined && (
                  <span
                    className={cn(
                      "inline-block size-2 border border-current",
                      item.selected && "bg-white",
                    )}
                  />
                )}
                {Icon && <Icon className="size-4" aria-hidden />}
                <span className="flex-1 truncate">{item.label}</span>
              </button>
            );
          })}
        </div>
      )}
    </div>
  );
}

"use client";

import { useEffect, useId, useRef, useState, type KeyboardEvent } from "react";

export type UseMenuOptions = {
  itemCount: number;
  /** Activate the item at the given index (Enter/Space on the highlighted row). */
  onActivate?: (i: number) => void;
};

export type UseMenuReturn = {
  open: boolean;
  setOpen: (open: boolean) => void;
  /** Index of the keyboard-highlighted item, or -1. */
  activeIndex: number;
  setActiveIndex: (i: number) => void;
  /** Wrap the trigger + dropdown; an outside click closes the menu. */
  containerRef: React.RefObject<HTMLDivElement | null>;
  /** Build a stable per-item id for aria-activedescendant wiring. */
  itemId: (i: number) => string;
  /** Spread onto the trigger button. */
  triggerProps: {
    "aria-haspopup": "menu";
    "aria-expanded": boolean;
    onClick: () => void;
    onKeyDown: (e: KeyboardEvent) => void;
  };
  /** Spread onto the menu container; handles arrow/Enter/Escape. */
  menuProps: {
    ref: React.RefObject<HTMLDivElement | null>;
    role: "menu";
    tabIndex: -1;
    "aria-activedescendant": string | undefined;
    onKeyDown: (e: KeyboardEvent) => void;
  };
  /** Call when an item is chosen — closes and resets. */
  onSelect: (run: () => void) => void;
};

/**
 * Headless action-menu behavior: open state, outside-click + Escape close, and
 * arrow-key navigation with a highlighted item. No styling.
 */
export function useMenu({ itemCount, onActivate }: UseMenuOptions): UseMenuReturn {
  const [open, setOpen] = useState(false);
  const [activeIndex, setActiveIndex] = useState(-1);
  const containerRef = useRef<HTMLDivElement>(null);
  const menuRef = useRef<HTMLDivElement>(null);
  const baseId = useId();

  // Keep the latest onActivate without re-subscribing handlers.
  const activateRef = useRef(onActivate);
  activateRef.current = onActivate;

  const itemId = (i: number) => `${baseId}-item-${i}`;

  useEffect(() => {
    if (!open) {
      setActiveIndex(-1);
      return;
    }
    // Focus the menu so its onKeyDown (Arrow/Enter/Escape) fires on open.
    menuRef.current?.focus();
    const onPointer = (e: MouseEvent) => {
      if (containerRef.current && !containerRef.current.contains(e.target as Node)) {
        setOpen(false);
      }
    };
    document.addEventListener("mousedown", onPointer);
    return () => document.removeEventListener("mousedown", onPointer);
  }, [open]);

  const move = (dir: 1 | -1) => {
    if (itemCount === 0) return;
    setActiveIndex((i) => {
      const next = i + dir;
      if (next < 0) return itemCount - 1;
      if (next > itemCount - 1) return 0;
      return next;
    });
  };

  const triggerKeyDown = (e: KeyboardEvent) => {
    if (e.key === "ArrowDown" || e.key === "Enter" || e.key === " ") {
      e.preventDefault();
      setOpen(true);
      setActiveIndex(0);
    }
  };

  const menuKeyDown = (e: KeyboardEvent) => {
    switch (e.key) {
      case "ArrowDown":
        e.preventDefault();
        move(1);
        break;
      case "ArrowUp":
        e.preventDefault();
        move(-1);
        break;
      case "Enter":
      case " ":
        if (activeIndex >= 0 && activeIndex < itemCount) {
          e.preventDefault();
          activateRef.current?.(activeIndex);
        }
        break;
      case "Escape":
        e.preventDefault();
        setOpen(false);
        break;
    }
  };

  return {
    open,
    setOpen,
    activeIndex,
    setActiveIndex,
    containerRef,
    itemId,
    triggerProps: {
      "aria-haspopup": "menu",
      "aria-expanded": open,
      onClick: () => setOpen(!open),
      onKeyDown: triggerKeyDown,
    },
    menuProps: {
      ref: menuRef,
      role: "menu",
      tabIndex: -1,
      "aria-activedescendant":
        activeIndex >= 0 && activeIndex < itemCount ? itemId(activeIndex) : undefined,
      onKeyDown: menuKeyDown,
    },
    onSelect: (run: () => void) => {
      run();
      setOpen(false);
    },
  };
}
